import asyncio
import os
from playwright.async_api import async_playwright

async def render():
    html_path = os.path.abspath("/app/output/samsung-galaxy-2025-infographic.html")
    output_path = "/app/output/final_poster.png"

    async with async_playwright() as p:
        browser = await p.chromium.launch(
            args=["--no-sandbox", "--disable-setuid-sandbox", "--disable-dev-shm-usage"]
        )
        # Use a square-ish viewport that lets the content render fully
        page = await browser.new_page(viewport={"width": 900, "height": 1400})

        await page.goto(f"file://{html_path}", wait_until="networkidle")
        await page.wait_for_timeout(3000)

        # Find the bounding box of the rendered SVG/canvas content
        bbox = await page.evaluate("""() => {
            const svg = document.querySelector('svg');
            if (svg) {
                const rect = svg.getBoundingClientRect();
                return {x: rect.x, y: rect.y, width: rect.width, height: rect.height};
            }
            const container = document.querySelector('#container');
            if (container) {
                const rect = container.getBoundingClientRect();
                return {x: rect.x, y: rect.y, width: rect.width, height: rect.height};
            }
            return null;
        }""")
        print(f"SVG bounding box: {bbox}")

        # Try to find the actual content bounds by looking at child elements
        content_bbox = await page.evaluate("""() => {
            const svg = document.querySelector('svg');
            if (!svg) return null;
            // Get all rects/text/groups inside svg and compute bounding box
            const allEls = svg.querySelectorAll('g, rect, text, circle');
            let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
            allEls.forEach(el => {
                try {
                    const rect = el.getBoundingClientRect();
                    if (rect.width > 0 && rect.height > 0) {
                        minX = Math.min(minX, rect.left);
                        minY = Math.min(minY, rect.top);
                        maxX = Math.max(maxX, rect.right);
                        maxY = Math.max(maxY, rect.bottom);
                    }
                } catch(e) {}
            });
            if (minX === Infinity) return null;
            return {x: Math.max(0, minX - 20), y: Math.max(0, minY - 20),
                    width: maxX - minX + 40, height: maxY - minY + 40};
        }""")
        print(f"Content bounding box: {content_bbox}")

        if content_bbox and content_bbox['width'] > 100 and content_bbox['height'] > 100:
            clip = content_bbox
        else:
            clip = {"x": 0, "y": 0, "width": 900, "height": 1400}

        await page.screenshot(
            path=output_path,
            full_page=False,
            clip=clip,
        )
        await browser.close()
        print(f"Poster saved to: {output_path}")
        print(f"Dimensions: {clip}")

asyncio.run(render())

